import itertools

def count_permutations(n, k):
    allowed = []
    for i in range(n):
        row = []
        for j in range(n):
            if (i - j) % n < k:
                row.append(j)
            else:
                row.append(None)
        allowed.append(row)

    count = 0
    for p in itertools.permutations(range(n)):
        valid = True
        for i in range(n):
            if p[i] not in allowed[i]:
                valid = False
                break
        if valid:
            count += 1
    return count

