def count_restricted(n, forbidden_offsets):
    # forbidden_offsets is a set of k such that sigma(j) != j+k (mod n)
    # For our problem, we want to count sigma such that sigma(j) \in {j+k | k not in forbidden_offsets}
    allowed_offsets = [k for k in range(n) if k not in forbidden_offsets]

    # This is the number of permutations sigma such that sigma(j) = j + a_j (mod n)
    # where a_j is in allowed_offsets.
    # This can be solved by finding the number of perfect matchings in a bipartite graph.
    # The bipartite graph has 2n nodes, with edges from i to (i + a) % n for a in allowed_offsets.

    import numpy as np

    adj = np.zeros((n, n), dtype=int)
    for i in range(n):
        for a in allowed_offsets:
            adj[i, (i + a) % n] = 1

    # The number of perfect matchings in a bipartite graph is the permanent of its adjacency matrix.
    # Since n is small, we can use the inclusion-exclusion principle or a simple recursion.

    memo = {}
    def permanent(matrix):
        n = len(matrix)
        def backtrack(row, mask):
            if row == n:
                return 1
            state = (row, mask)
            if state in memo:
                return memo[state]

            res = 0
            for col in range(n):
                if (mask & (1 << col)) and matrix[row][col]:
                    res += backtrack(row + 1, mask ^ (1 << col))

            memo[state] = res
            return res

        memo = {}
        return backtrack(0, (1 << n) - 1)

    return permanent(adj)

